versions.variantCss:
.wemd-stats-block[data-variant="bytedance-stats-bold"] {
  background: var(--wemd-bg-card);
  border-radius: var(--wemd-border-radius);
  padding: 24px 28px;
  margin: 16px 0;
  border: 1px solid var(--wemd-border-soft);
  box-shadow: var(--wemd-shadow);
}
.wemd-stats-block[data-variant="bytedance-stats-bold"] .wemd-component-body {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-around;
}
.wemd-stats-block[data-variant="bytedance-stats-bold"] .wemd-component-body .wemd-child-1 {
  color: var(--wemd-primary);
  font-size: 32px;
  font-weight: 700;
  line-height: 1.2;
  margin: 0;
}
.wemd-stats-block[data-variant="bytedance-stats-bold"] .wemd-component-body .wemd-child-2 {
  color: var(--wemd-text-soft);
  font-size: 13px;
  margin: 0;
}
.wemd-stats-block[data-variant="bytedance-stats-bold"] .wemd-component-body .wemd-child-3 {
  color: var(--wemd-secondary);
  font-size: 32px;
  font-weight: 700;
  line-height: 1.2;
  margin: 0;
}
.wemd-stats-block[data-variant="bytedance-stats-bold"] .wemd-component-body .wemd-child-4 {
  color: var(--wemd-text-soft);
  font-size: 13px;
  margin: 0;
}
